      es: ["Antigua mina de manganeso", "Reliquia industrial", "Costa este de Efate", "Operativa hasta 1978"],
      pt: ["Antiga mina de manganês", "Relíquia industrial", "Costa leste de Efate", "Operacional até 1978"],
      fr: ["Ancienne mine de manganèse", "Relique industrielle", "Côte est d'Efate", "Activité jusqu'en 1978"],
